function validate([cuboids]) {
  if (!Array.isArray(cuboids) || cuboids.length < 1 || cuboids.length > 100) return 'cuboids needs 1 to 100 boxes.';
  for (const box of cuboids) {
    if (!Array.isArray(box) || box.length !== 3) return 'Each cuboid has exactly three measurements.';
    if (box.some((v) => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each measurement is an integer from 1 to 100.';
  }
  return null;
}

