function maxHeight(cuboids) {
  const boxes = cuboids.map((cuboid) => [...cuboid].sort((a, b) => a - b));
  boxes.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);
  const dp = new Array(boxes.length).fill(0);
  let best = 0;

  for (let i = 0; i < boxes.length; i++) {
    dp[i] = boxes[i][2];
    for (let j = 0; j < i; j++) {
      const fits = boxes[j][0] <= boxes[i][0] && boxes[j][1] <= boxes[i][1] && boxes[j][2] <= boxes[i][2];
      if (fits) {
        dp[i] = Math.max(dp[i], dp[j] + boxes[i][2]);
      }
    }
    best = Math.max(best, dp[i]);
  }
  return best;
}

