function maxHeight(cuboids) {
  // Try every unused box in every one of its six orientations on top of the current one.
  const n = cuboids.length;
  const orders = [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]];
  const memo = new Map();
  const tallest = (used, w, l, h) => {
    const key = used + ':' + w + ':' + l + ':' + h;
    if (memo.has(key)) return memo.get(key);
    let most = 0;
    for (let k = 0; k < n; k++) {
      if (used & (1 << k)) continue;
      for (const order of orders) {
        const [a, b, c] = order.map((x) => cuboids[k][x]);
        if (a <= w && b <= l && c <= h) most = Math.max(most, c + tallest(used | (1 << k), a, b, c));
      }
    }
    memo.set(key, most);
    return most;
  };
  return tallest(0, 1000, 1000, 1000);
}

