function generate(rand, size) {
  const n = size === 'large' ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 7);
  const high = size === 'large' ? 100 : [3, 6, 15][Math.floor(rand() * 3)];
  const cuboids = Array.from({ length: n }, () => [0, 0, 0].map(() => 1 + Math.floor(rand() * high)));
  return [cuboids];
}
